// ====== CONFIG ======
const SOURCE_NODE = 'formataConfiguracoes';   // nó que formata os flows

// ==================== agoraMenos ====================
try {
  // Fonte
  const nodeData = $(SOURCE_NODE).all();
  if (!nodeData || nodeData.length === 0) {
    throw new Error(`Dados do nó "${SOURCE_NODE}" não encontrados.`);
  }

  // ===== Helpers =====
  function parseTempo(tempoStr) {
    if (typeof tempoStr !== 'string') {
      throw new Error(`Valor de tempo inválido: ${tempoStr} (não é string)`);
    }
    const match = tempoStr.match(/^(\d+)(min|h|s)$/);
    if (!match) {
      throw new Error(`Formato de tempo inválido: ${tempoStr} (use <número>min, <número>h ou <número>s)`);
    }
    return { value: parseInt(match[1], 10), unit: match[2] };
  }
  function toMinutes(value, unit) {
    if (unit === 'min') return value;
    if (unit === 'h')   return value * 60;
    if (unit === 's')   return value / 60;
    throw new Error(`Unidade de tempo não reconhecida: ${unit}`);
  }
  function toSeconds(value, unit) {
    if (unit === 'min') return value * 60;
    if (unit === 'h')   return value * 3600;
    if (unit === 's')   return value;
    throw new Error(`Unidade de tempo não reconhecida: ${unit}`);
  }
  function agoraMenosISO(minutos) {
    if (typeof minutos !== 'number' || isNaN(minutos) || minutos < 0) {
      throw new Error(`Valor de minutos inválido: ${minutos} (tipo: ${typeof minutos})`);
    }
    const ms = minutos * 60 * 1000;
    const data = new Date(Date.now() - ms);
    // ISO “sv-SE” + offset fixo -03:00 (America/Sao_Paulo)
    return (
      data
        .toLocaleString('sv-SE', {
          timeZone: 'America/Sao_Paulo',
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
        })
        .replace(' ', 'T') + '-03:00'
    );
  }

  const results = [];

  nodeData.forEach((item) => {
    const cfg = item?.json;
    if (!cfg || typeof cfg !== 'object') return;

    // Identificação (OBRIGATÓRIO)
    const followup_flow_name = cfg.followup_flow_name;
    if (typeof followup_flow_name !== 'string' || followup_flow_name.trim() === '') {
      throw new Error(
        `agoraMenos: 'followup_flow_name' ausente ou vazio no item de entrada. ` +
        `Garanta que '${SOURCE_NODE}' emita 'followup_flow_name' para cada fluxo.`
      );
    }

    const agent = cfg.agent ?? null;

    // Cadências (mantém unidade original)
    const cadList = Array.isArray(cfg.cadencia) ? cfg.cadencia : [];
    const parsedIntervals = cadList
      .map((str) => {
        try {
          const p = parseTempo(str);
          return {
            original: str,
            value: p.value,
            unit: p.unit,
            minutes: toMinutes(p.value, p.unit),
            seconds: toSeconds(p.value, p.unit),
          };
        } catch {
          return null; // ignora itens inválidos
        }
      })
      .filter(Boolean);

    // Espera sem resposta
    const esperaRaw =
      cfg.esperaSemResposta === '' || cfg.esperaSemResposta == null
        ? null
        : String(cfg.esperaSemResposta);

    let esperaSemResposta = false;
    let esperaInterval = null;

    if (esperaRaw !== null) {
      try {
        const p = parseTempo(esperaRaw);
        esperaSemResposta = true;
        esperaInterval = {
          original: esperaRaw,
          value: p.value,
          unit: p.unit,
          minutes: toMinutes(p.value, p.unit),
          seconds: toSeconds(p.value, p.unit),
        };
      } catch {
        esperaSemResposta = false;
        esperaInterval = null;
      }
    }

    // Se não houver nenhum intervalo válido e também não houver espera válida, ignora
    if (parsedIntervals.length === 0 && !esperaInterval) return;

    // Se houver espera válida, ela entra por último nas listas
    const finalIntervals = [...parsedIntervals];
    if (esperaInterval) finalIntervals.push(esperaInterval);

    // ==== ALTERAÇÃO: chaves únicas com índice -> agoraMenos{valor}{unidade}_{i}
    const agoraMenos = {};
    finalIntervals.forEach((x, i) => {
      const key = `agoraMenos${x.value}${x.unit}_${i}`;
      agoraMenos[key] = agoraMenosISO(x.minutes);
    });

    // intervalos
    const intervalos = {
      segundos: finalIntervals.map((x) => x.seconds),
      minutos:  finalIntervals.map((x) => x.minutes),
      horas:    finalIntervals.map((x) => Math.round((x.minutes / 60) * 100) / 100),
      total:    finalIntervals.length,
    };

    // Output final
    const out = {
      followup_flow_name,   
      agent,
      esperaSemResposta,    // booleano
      intervalos,           // segundos, minutos, horas, total
      agoraMenos            // { agoraMenos2s_0, agoraMenos2s_1, agoraMenos2h_3, ... }
    };

    results.push({ json: out });
  });

  if (results.length === 0) {
    throw new Error(`Nenhum resultado válido foi gerado a partir de "${SOURCE_NODE}".`);
  }

  return results;

} catch (error) {
  return [{
    json: {
      erro: true,
      mensagem: error.message,
      timestamp: new Date().toISOString(),
      tipoErro: 'processamento_followup',
    }
  }];
}

// ====== CONFIG ======
const SOURCE_NODE = 'formataConfiguracoes';
const PIPES_NODE  = 'buscaFunisEtapas';

// ====== Helpers (normalização e afins) ======
function normStrict(str){return String(str??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');}
function normLight(str){return String(str??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();}
function tokenBagKey(str){const t=String(str??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().match(/[a-z0-9]+/g)||[];t.sort();return t.join('|');}
function makeKeys(str){return [normStrict(str),normLight(str),tokenBagKey(str)];}
function isEmptyListOrString(v){if(v==null)return true;if(Array.isArray(v))return v.length===0;if(typeof v==='string')return v.trim()==='';return false;}
function manualDeCorrecao(){return `Manual:
1) Você pode informar por NOME: "NOME DO FUNIL - NOME DA ETAPA".
2) Ou por ID: "pipelineId-statusId".
3) Nomes ignoram acentos/maiúsculas/espaços/pontuação.
4) Em duplicidade, informe por ID.

Ajuda: use os nomes exatamente como aparecem no Kommo (ou IDs).`;}
function listarFunisDisponiveis(pipes){return pipes.map(p=>`- ${p.name} (id: ${p.id})`).join('\n');}
function listarEtapasDisponiveis(p){const sts=(p?._embedded?.statuses||[]).map(s=>`- ${s.name} (id: ${s.id})`).join('\n');return sts||'(nenhuma etapa encontrada)';}
function throwEr(headerLine,flowName,body){throw new Error(`${headerLine}
[confereFunisEtapas] Flow "${flowName}" — não reconhecido
${body}

${manualDeCorrecao()}`);}

function splitFunilEtapa(raw){
  const s=String(raw??''); const i=s.indexOf('-');
  if(i===-1) return {ok:false,reason:'semHifen',funilRaw:s.trim(),etapaRaw:''};
  const f=s.slice(0,i).trim(); const e=s.slice(i+1).trim();
  if(!f && !e) return {ok:false,reason:'vazioDuplo',funilRaw:f,etapaRaw:e};
  if(!f)       return {ok:false,reason:'semFunil',funilRaw:f,etapaRaw:e};
  if(!e)       return {ok:false,reason:'semEtapa',funilRaw:f,etapaRaw:e};
  return {ok:true,funilRaw:f,etapaRaw:e};
}

// ====== Indexação dos pipelines ======
function buildIndexes(pipelinesRaw){
  const pipelineById = new Map();
  const pipelinesByName = new Map();
  const statusByPipelineAndId = new Map();
  const statusKeysByPipelineId = new Map();

  for (const p of pipelinesRaw){
    pipelineById.set(String(p.id), p);

    const pn = normStrict(p?.name ?? '');
    if (pn){
      if (!pipelinesByName.has(pn)) pipelinesByName.set(pn, []);
      pipelinesByName.get(pn).push(p);
    }

    const keyMap = new Map();
    for (const s of (p?._embedded?.statuses||[])){
      statusByPipelineAndId.set(`${p.id}-${s.id}`, s);
      for (const k of makeKeys(s?.name ?? '')){
        if(!k) continue;
        if(!keyMap.has(k)) keyMap.set(k, []);
        keyMap.get(k).push(s);
      }
    }
    statusKeysByPipelineId.set(p.id, keyMap);
  }

  return { pipelineById, pipelinesByName, statusByPipelineAndId, statusKeysByPipelineId, pipelinesRaw };
}

function resolveFunilEtapaToId(rawPair, flowName, indexes){
  const { pipelineById, pipelinesByName, statusByPipelineAndId, statusKeysByPipelineId, pipelinesRaw } = indexes;
  const parsed = splitFunilEtapa(rawPair);

  if (!parsed.ok){
    let motivo='Formato inválido.'; 
    if (parsed.reason==='semHifen')   motivo='Falta o hífen "-" separando FUNIL e ETAPA.';
    if (parsed.reason==='semFunil')   motivo='Falta o nome/ID do FUNIL antes do "-".';
    if (parsed.reason==='semEtapa')   motivo='Falta o nome/ID da ETAPA depois do "-".';
    if (parsed.reason==='vazioDuplo') motivo='Faltam FUNIL e ETAPA.';
    throwEr(`"${parsed.funilRaw||''} - ${parsed.etapaRaw||''}"`, flowName, `Detalhes:\n- Motivo: ${motivo}`);
  }

  const { funilRaw, etapaRaw } = parsed;

  // Por ID
  if (/^\d+$/.test(funilRaw) && /^\d+$/.test(etapaRaw)){
    const pipeline = pipelineById.get(funilRaw);
    if (!pipeline){
      throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Motivo: FUNIL por ID não encontrado.\n\nFunis disponíveis:\n${listarFunisDisponiveis(pipelinesRaw)}`);
    }
    const status = statusByPipelineAndId.get(`${funilRaw}-${etapaRaw}`);
    if (!status){
      throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Funil reconhecido: "${pipeline.name}" (id ${pipeline.id})\n- Motivo: ETAPA por ID não encontrada neste funil.\n\nEtapas disponíveis no funil "${pipeline.name}" (id ${pipeline.id}):\n${listarEtapasDisponiveis(pipeline)}`);
    }
    return `${pipeline.id}-${status.id}`;
  }

  // Por nome
  const funilKey = normStrict(funilRaw);
  const etapaKeys = makeKeys(etapaRaw);
  const candidatesPipes = pipelinesByName.get(funilKey) || [];
  if (!candidatesPipes.length){
    throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Motivo: FUNIL não localizado.\n\nFunis disponíveis:\n${listarFunisDisponiveis(pipelinesRaw)}`);
  }

  let pipeline = null;
  if (candidatesPipes.length===1){
    pipeline = candidatesPipes[0];
  } else {
    const withStage = candidatesPipes.filter(p => {
      const km = statusKeysByPipelineId.get(p.id) || new Map();
      return etapaKeys.some(k => km.has(k));
    });
    if (withStage.length===1) pipeline = withStage[0];
    else {
      const lista = candidatesPipes.map(p=>`- ${p.name} (id: ${p.id})`).join('\n');
      throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Motivo: FUNIL ambíguo (mesmo nome em ${candidatesPipes.length} funis) e não foi possível decidir pela etapa.\n\nFunis candidatos:\n${lista}`);
    }
  }

  const km = statusKeysByPipelineId.get(pipeline.id) || new Map();
  let candidatesStatus = [];
  for (const k of etapaKeys){ if (km.has(k)) candidatesStatus = candidatesStatus.concat(km.get(k)); }
  candidatesStatus = Array.from(new Map(candidatesStatus.map(s=>[String(s.id), s])).values());

  if (!candidatesStatus.length){
    throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Funil reconhecido: "${pipeline.name}" (id ${pipeline.id})\n- Motivo: ETAPA não encontrada neste funil.\n\nEtapas disponíveis no funil "${pipeline.name}" (id ${pipeline.id}):\n${listarEtapasDisponiveis(pipeline)}`);
  }
  if (candidatesStatus.length>1){
    throwEr(`"${funilRaw} - ${etapaRaw}"`, flowName,`Detalhes:\n- Motivo: múltiplas ETAPAS com o mesmo nome neste funil. Informe por ID no formato "pipelineId-statusId".\n\nOpções de etapa encontradas:\n${candidatesStatus.map(s=>`- ${s.name} (id: ${s.id})`).join('\n')}`);
  }

  return `${pipeline.id}-${candidatesStatus[0].id}`;
}

// ====== 1) Carrega pipelines do nó "buscaFunisEtapas" ======
const pipesItems = $(PIPES_NODE).all();
if (!pipesItems.length) {
  throw new Error(`confereFunisEtapas: o nó "${PIPES_NODE}" não retornou itens.
📋 TUTORIAL: Conecte o nó que chama a API de pipelines do Kommo antes deste e rode novamente.`);
}

// Suporta diferentes formatos de retorno
let pipelinesRaw = [];
for (const it of pipesItems){
  const j = it?.json || it || {};
  if (Array.isArray(j?.pipelines)) pipelinesRaw = pipelinesRaw.concat(j.pipelines);
  else if (j?._embedded?.pipelines) pipelinesRaw = pipelinesRaw.concat(j._embedded.pipelines);
  else if (Array.isArray(j) && j[0]?._embedded?.pipelines) pipelinesRaw = pipelinesRaw.concat(j[0]._embedded.pipelines);
}
pipelinesRaw = Array.from(new Map(pipelinesRaw.map(p=>[String(p.id), p])).values()); // dedup por id

if (!pipelinesRaw.length){
  throw new Error(`confereFunisEtapas: não encontrei "_embedded.pipelines" no output de "${PIPES_NODE}".`);
}

const indexes = buildIndexes(pipelinesRaw);

// ====== 2) Carrega FLOWS do "formataConfiguracoes" ======
const flowsItems = $(SOURCE_NODE).all();
if (!flowsItems.length) {
  throw new Error(`confereFunisEtapas: o nó "${SOURCE_NODE}" não retornou itens.`);
}

// ====== 3) Resolve para cada flow usando o ÚNICO conjunto de pipelines ======
const out = [];

for (const it of flowsItems){
  const flow = { ...(it.json || {}) };
  const flowName = flow.followup_flow_name ?? '(sem nome)';

  const funisEtapas_id = !isEmptyListOrString(flow.funisEtapas)
    ? (Array.isArray(flow.funisEtapas)
        ? flow.funisEtapas.map(f => resolveFunilEtapaToId(f, flowName, indexes))
        : [resolveFunilEtapaToId(flow.funisEtapas, flowName, indexes)]
      )
    : null;

  const funilEtapaSemResposta_id = !isEmptyListOrString(flow.funilEtapaSemResposta)
    ? resolveFunilEtapaToId(flow.funilEtapaSemResposta, flowName, indexes)
    : null;

  // >>> Sem tags no output <<<
  const minimal = {
    followup_flow_name: flow.followup_flow_name,
    agent: flow.agent,
    funisEtapas: flow.funisEtapas,
    funisEtapas_id,
    funilEtapaSemResposta: flow.funilEtapaSemResposta,
    funilEtapaSemResposta_id
  };

  out.push({ json: minimal });
}

return out;

const dias = ['domingo', 'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'sabado'];

// Hora atual com fuso São Paulo
const fuso = 'America/Sao_Paulo';
const agora = new Date();

// Usa Intl.DateTimeFormat para extrair hora no fuso correto
const formatadorHora = new Intl.DateTimeFormat('pt-BR', {
  timeZone: fuso,
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
});

const horaStr = formatadorHora.format(agora); // ex: "18:34:22"
const [hora, minuto, segundo] = horaStr.split(':').map(Number);
const horaDecimal = hora + minuto / 60;

// Para extrair a data no fuso horário correto:
const formatadorData = new Intl.DateTimeFormat('pt-BR', {
  timeZone: fuso,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});

const partesData = formatadorData.formatToParts(agora);

let ano, mes, dia;
for (const parte of partesData) {
  if (parte.type === 'year') ano = parte.value;
  if (parte.type === 'month') mes = parte.value;
  if (parte.type === 'day') dia = parte.value;
}

const dataHoraAtual = `${ano}-${mes}-${dia}T${String(hora).padStart(2, '0')}:${String(minuto).padStart(2, '0')}:${String(segundo).padStart(2, '0')}`;

const diaSemana = dias[agora.getDay()];
const config = $('configuracoesHorarioComercial').first().json;
const intervalo = config[diaSemana]; // ex: "7,19"

let permitido = false;

if (intervalo && intervalo !== "0-0") {
  const [inicioStr, fimStr] = intervalo.split('-');
  const inicio = parseFloat(inicioStr);
  const fim = parseFloat(fimStr);

  permitido = horaDecimal >= inicio && horaDecimal < fim;
}

return [
  {
    json: {
      permitido: permitido,
      dataHoraAtual: dataHoraAtual
    }
  }
];

/**
 * formataConfiguracoes (Run Once for ALL Items)
 * - Valida o nó "configuracoesAcessos"
 * - Lê e valida o nó "configuracoesFollowUp"
 * - Gera 1 item por fluxo, SEM carregar dados de acesso no output
 * - ⚠️ Sem o campo "extraNodes"
 * - ⚠️ esperaSemResposta AGORA É OBRIGATÓRIO (padrão "<número>(s|min|h)")
 */

const NODE_ACESSOS = 'configuracoesAcessos';
const NODE_CONFIGS = 'configuracoesFollowUp';

// ===== Helpers =====
const EXPECTED_ACCESS_KEYS = [
  'subdomainKommo',
  'projectNameDatabase',       // <- trocado para projectNameDatabase
  'tokenKommo',
  'serviceSecretDatabase',
  'tokenKommetrik',
];

// ⚠️ Sem "extraNodes"
const FLOW_KEYS = [
  'agent', 'tags_permitidas',
  'funisEtapas', 'cadencia', 'funilEtapaSemResposta',
  'esperaSemResposta', 'prompt',
];

function isString(v) { return typeof v === 'string'; }
function isEmptyString(v) { return isString(v) && v.trim() === ''; }
function toNullIfEmpty(v) {
  if (v === null || v === undefined) return null;
  if (isString(v) && v.trim() === '') return null;
  if (Array.isArray(v) && v.length === 0) return null;
  return v;
}
function hasHyphen(str) { return String(str).includes('-'); }
function isTempoString(str) { return /^(\d+)(min|h|s)$/.test(String(str)); }
function tutorial(msg) {
  return `${msg}
📍 Como corrigir:
1) Abra o nó indicado (Set) e ajuste o(s) campo(s) conforme a mensagem.
2) 'esperaSemResposta' é obrigatório e deve seguir "<número>min|h|s" (ex.: "1440min", "2h", "30s").
3) Salve e rode o fluxo novamente.`;
}
function getNodeItemsByName(name) {
  try {
    const arr = $items(name);
    if (!Array.isArray(arr) || arr.length === 0) {
      throw new Error(`Sem itens no nó "${name}".`);
    }
    return arr;
  } catch (e) {
    throw new Error(`Nó não encontrado: "${name}".`);
  }
}

// ===== 1) Validação de configuracoesAcessos =====
const acessosItem = getNodeItemsByName(NODE_ACESSOS)[0];
const acessos = acessosItem?.json;

if (!acessos || typeof acessos !== 'object' || Array.isArray(acessos)) {
  throw new Error(tutorial(
    `Estrutura inválida em "${NODE_ACESSOS}". Esperado: um OBJETO com os campos ${EXPECTED_ACCESS_KEYS.join(', ')}.`
  ));
}

const keysAcessos = Object.keys(acessos);
const missing = EXPECTED_ACCESS_KEYS.filter(k => !(k in acessos));
const extras = keysAcessos.filter(k => !EXPECTED_ACCESS_KEYS.includes(k));
if (missing.length) {
  throw new Error(tutorial(`Campo(s) ausente(s) em "${NODE_ACESSOS}": ${missing.join(', ')}.`));
}
if (extras.length) {
  throw new Error(tutorial(
    `Campo(s) não permitido(s) em "${NODE_ACESSOS}": ${extras.join(', ')}.
Somente são aceitos: ${EXPECTED_ACCESS_KEYS.join(', ')}.`
  ));
}
for (const k of EXPECTED_ACCESS_KEYS) {
  if (!isString(acessos[k])) throw new Error(tutorial(`Campo "${k}" em "${NODE_ACESSOS}" deve ser STRING.`));
  if (isEmptyString(acessos[k])) throw new Error(tutorial(`Campo "${k}" em "${NODE_ACESSOS}" não pode estar vazio.`));
}
if (/^https?:\/\//i.test(acessos.subdomainKommo) || acessos.subdomainKommo.includes('.kommo.com')) {
  throw new Error(tutorial(
    `Campo "subdomainKommo" inválido em "${NODE_ACESSOS}".
Use apenas o subdomínio (ex.: "metriksales"), sem "http(s)://" e sem ".kommo.com".`
  ));
}
if (/^https?:\/\//i.test(acessos.projectNameDatabase)) {
  throw new Error(tutorial(
    `Campo "projectNameDatabase" inválido em "${NODE_ACESSOS}".
Use o "project ref" do Supabase (ex.: "rdildqbfggihmceqwyoc"), sem "http(s)://".`
  ));
}

// ===== 2) Leitura + validação de configuracoesFollowUp (sem "extraNodes") =====
const cfgItems = getNodeItemsByName(NODE_CONFIGS);
const raw = cfgItems[0]?.json;
const cfgRoot = Array.isArray(raw) ? raw[0] : raw;

if (!cfgRoot || typeof cfgRoot !== 'object' || Array.isArray(cfgRoot)) {
  throw new Error(tutorial(
    `Estrutura inválida em "${NODE_CONFIGS}".
Esperado: um OBJETO com vários blocos nomeados (ex.: {"meu_flow": { ... }}).`
  ));
}

const out = [];

for (const [flowName, value] of Object.entries(cfgRoot)) {
  const key = String(flowName || '').trim();
  if (!key) throw new Error(tutorial(`Nome do bloco (chave do objeto) em "${NODE_CONFIGS}" não pode ser vazio.`));

  const isPlainObject = value && typeof value === 'object' && !Array.isArray(value);
  if (!isPlainObject) {
    throw new Error(tutorial(`O conteúdo de "${key}" em "${NODE_CONFIGS}" deve ser um OBJETO.`));
  }

  // somente os campos em FLOW_KEYS são aceitos
  for (const campo of FLOW_KEYS) {
    if (!(campo in value)) {
      throw new Error(tutorial(`Campo '${campo}' ausente no bloco "${key}" (nó "${NODE_CONFIGS}").`));
    }
  }
  for (const campo of Object.keys(value)) {
    if (!FLOW_KEYS.includes(campo)) {
      throw new Error(tutorial(
        `Campo '${campo}' não é permitido no bloco "${key}" (nó "${NODE_CONFIGS}").
Use apenas: ${FLOW_KEYS.join(', ')}.`
      ));
    }
  }

  // validações de conteúdo
  if (value.agent !== null && value.agent !== undefined && !isString(value.agent)) {
    throw new Error(tutorial(`Campo 'agent' deve ser string (pode ser vazio "") no bloco "${key}".`));
  }
  const agentFinal = toNullIfEmpty(value.agent);

  if (!Array.isArray(value.tags_permitidas)) {
    throw new Error(tutorial(`Campo 'tags_permitidas' deve ser array no bloco "${key}".`));
  }
  if (value.tags_permitidas.length > 0 && !value.tags_permitidas.every(isString)) {
    throw new Error(tutorial(`'tags_permitidas' deve conter apenas strings no bloco "${key}".`));
  }
  const tagsFinal = toNullIfEmpty(value.tags_permitidas);

