  // ===== Fonte =====
  const loopItems = $('iteraFluxos').all();
  if (!loopItems || loopItems.length === 0) {
    throw new Error('Nenhum dado recebido de "iteraFluxos".');
  }

  // ===== Helpers =====
  function toUTCNoMs(iso) {
    if (typeof iso !== 'string' || !iso) return iso;
    const d = new Date(iso);                 // respeita offset se houver
    if (isNaN(d.getTime())) return iso;      // fallback: devolve como veio
    return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); // remove ms
  }

function labelFromKey(key, fallbackMinutes) {
  const s = String(key || '');
  // suporta: agoraMenos2s_0 | agoraMenos30min | agoraMenos2h_3
  const m = s.match(/^agoraMenos(\d+)(min|h|s)(?:_\d+)?$/i);
  if (m) {
    return `${m[1]}${m[2]} atrás`;
  }
  // fallback (quando a chave não segue o padrão)
  return `${fallbackMinutes}min atrás`;
}

  const out = [];

  for (const it of loopItems) {
    const root = it?.json || {};
    const flowName =
      root.followup_flow_name ||
      root?.formataConfiguracoes?.followup_flow_name ||
      root.follow_flow_name || // fallback legado, se ainda existir em algum teste
      '';

    // Bloco agoraMenos (gerado pelo nó "agoraMenos")
    const ag = root.agoraMenos || {};
    const esperaSemResposta = !!ag.esperaSemResposta;

    // Listas com MESMO comprimento e mesma ordem
    const minutosArr = Array.isArray(ag?.intervalos?.minutos) ? ag.intervalos.minutos : [];
    const agoraObj   = (ag && typeof ag.agoraMenos === 'object') ? ag.agoraMenos : {};

    const keys = Object.keys(agoraObj); // ex.: ["agoraMenos15min","agoraMenos2h",...]
    if (!keys.length || !minutosArr.length) continue;

    const n = Math.min(keys.length, minutosArr.length);
    const ultimoIndex = n - 1;

    for (let i = 0; i < n; i++) {
      const key = keys[i];                    // p.ex. "agoraMenos15min"
      const minutes = minutosArr[i];          // p.ex. 15 (em minutos)
      const tsUTC = toUTCNoMs(agoraObj[key]); // sempre UTC

      const row = {
        intervalo_index: i,                      // índice do intervalo atual
        followup_flow_name: flowName,            // identificação do flow 
        agoraMenos: tsUTC,                       // timestamp UTC
        quantoAtras: labelFromKey(key, minutes), // "15min atrás", "2h atrás", ...
        ultimoCount: (i === ultimoIndex) && esperaSemResposta
      };

      out.push({ json: row });
    }
  }

  if (!out.length) throw new Error('Nenhum item de intervalo foi gerado.');

  return out;

} catch (error) {
