// validaLeads — compara DB x Kommo e sempre resolve funilEtapa por NOME se possível
// usando buscaFunisEtapas como fonte de nomes por ID.
// Em último caso, funilEtapa vira "pipeline_id-status_id" (nunca null).

try {
  // ---------- Entradas ----------
  const dbRows   = $('buscaLeadsDatabase').all().map(it => it.json || it) || [];
  const kommoRaw = $('filtraLeadsKommo').all().map(it => it.json || it) || [];
  if (!dbRows.length) throw new Error('validaLeads: nenhum item em "buscaLeadsDatabase".');

  // iteraFluxos: referências de regras do fluxo atual
  const flowRoot   = $('iteraFluxos').first()?.json || {};
  const refFunis   = flowRoot.confereFunisEtapas || {};
  const refTags    = flowRoot.confereTags || {};

  // ---------- Mapeia pipelines/status (buscaFunisEtapas) ----------
  const pipesItems = $('buscaFunisEtapas').all().map(it => it.json || it) || [];
  let pipelines = [];
  for (const j of pipesItems) {
    if (Array.isArray(j?.pipelines)) pipelines = pipelines.concat(j.pipelines);
    else if (j?._embedded?.pipelines) pipelines = pipelines.concat(j._embedded.pipelines);
    else if (Array.isArray(j) && j[0]?._embedded?.pipelines) pipelines = pipelines.concat(j[0]._embedded.pipelines);
  }
  // dedup por id
  const seen = new Set(); pipelines = pipelines.filter(p => !seen.has(String(p.id)) && seen.add(String(p.id)));

  const pipelineNameById = new Map();                  // "11733016" -> "Celulares"
  const statusNameByPidSid = new Map();                // "11733016-90241016" -> "Contato Inicial ..."
  for (const p of pipelines) {
    pipelineNameById.set(String(p.id), String(p?.name ?? ''));
    for (const s of (p?._embedded?.statuses || [])) {
      statusNameByPidSid.set(`${p.id}-${s.id}`, String(s?.name ?? ''));
    }
  }

  // ---------- Índices de referência do fluxo ----------
  const refIds   = Array.isArray(refFunis.funisEtapas_id) ? refFunis.funisEtapas_id.map(String) : [];
  const refTagIds   = Array.isArray(refTags.tags_permitidas_id) ? refTags.tags_permitidas_id.map(n => Number(n)) : [];
  const refTagNames = Array.isArray(refTags.tags_permitidas) ? refTags.tags_permitidas.map(t => String(t).trim().toLowerCase()) : [];

  // ---------- Indexa leads do Kommo por ID ----------
  const kommoLeads = [];
  for (const it of kommoRaw) {
    const emb = it?._embedded?.leads;
    if (Array.isArray(emb)) kommoLeads.push(...emb);
  }
  const kommoById = new Map(kommoLeads.map(l => [String(l.id), l]));

  // ---------- Helpers ----------
  const norm = s => String(s ?? '').trim().toLowerCase();
  function extractTags(lead) {
    const list = Array.isArray(lead?._embedded?.tags) ? lead._embedded.tags : [];
    return {
      names: list.map(t => String(t?.name ?? '')).filter(Boolean),
      ids:   list.map(t => t?.id).filter(v => Number.isFinite(Number(v))).map(Number),
    };
  }
  function tagsPermitidasFor(leadTags) {
    if (!refTagIds.length && !refTagNames.length) return true;
    const byId   = refTagIds.length   ? leadTags.ids.some(id => refTagIds.includes(id)) : false;
    const byName = refTagNames.length ? leadTags.names.map(norm).some(n => refTagNames.includes(n)) : false;
    return byId || byName;
  }

  // ---------- Saída ----------
  const out = [];
  for (const row of dbRows) {
    const rowId = String(row?.entity_id ?? '').trim();
    const kLead = kommoById.get(rowId) || null;

    let funilEtapa_id = null;
    let funilEtapa    = null;
    let tags = [], tags_id = [];

    if (kLead) {
      // IDs
      const pid = String(kLead.pipeline_id);
      const sid = String(kLead.status_id);
      funilEtapa_id = `${pid}-${sid}`;

      // Nomes por buscaFunisEtapas (preferencial), senão cai para IDs
      const pipeName = pipelineNameById.get(pid) || null;
      const statName = statusNameByPidSid.get(funilEtapa_id) || null;
      funilEtapa = (pipeName || statName)
        ? `${pipeName || pid}-${statName || sid}`
        : `${pid}-${sid}`;

      // Tags do Kommo
      const tg = extractTags(kLead);
      tags = tg.names;
      tags_id = tg.ids;
    }

    const leadExiste = !!kLead;
    const funilEtapaPermitido =
      leadExiste ? (refIds.length ? refIds.includes(funilEtapa_id) : true) : false;
    const tagsPermitidas = leadExiste ? tagsPermitidasFor({ names: tags, ids: tags_id }) : false;

    out.push({
      json: {
        validacao: { leadExiste, funilEtapaPermitido, tagsPermitidas },
        funilEtapa,          // nunca null; pelo menos "pid-sid"
        funilEtapa_id,       // se não achou lead, fica null
        tags,
        tags_id,
        databaseRow: row,
        kommoLead: kLead
      }
    });
  }

  return out;

} catch (err) {
  throw err; // erro deve parar o fluxo
}

